import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Create container
  const container = new Group();

  // Parse colors
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const cInk = new Color(colors.ink);
  const cPaper = new Color(colors.paper);
  const cAccent = new Color(colors.accent);
  const cSurface = new Color(colors.surface);

  // Timelines list for cleanup
  const activeTimelines = [];

  // Create visual card geometry (1.6 x 1.0)
  const width = 1.6;
  const height = 1.0;
  const cardGeometry = new PlaneGeometry(width, height);

  // Create TSL material representing the "engineered gradient surface" with subtle grain
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });

  // TSL Color node
  const uvNode = uv();

  // Base engineered vertical gradient from bottom (surface) to top (ink)
  const gradient = mix(
    vec3(cSurface.r, cSurface.g, cSurface.b),
    vec3(cInk.r, cInk.g, cInk.b),
    uvNode.y
  );

  // Add subtle grain using a simple pseudo-random noise generator on UV
  const noise = frac(sin(uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233))).mul(43758.5453));
  const grainAmount = 0.04;
  const finalBackground = mix(gradient, vec3(noise), grainAmount);

  // Define fragment shader output
  material.colorNode = vec4(finalBackground, 1.0);

  // Primary backing mesh
  const cardMesh = new Mesh(cardGeometry, material);
  container.add(cardMesh);

  // Load and place the image texture (orb-decor.png) if provided
  const imageUrl = config.imageUrl || (config.intent?.visualSpec?.assets && config.intent.visualSpec.assets.imageUrl);
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      // Create overlay mesh with additive blending on top of background
      const overlayGeo = new PlaneGeometry(0.8, 0.8);
      const overlayMat = new MeshBasicNodeMaterial({
        color: cAccent, // Multiply or color overlay with accent
        map: texture,
        transparent: true,
        depthWrite: false,
        blending: ctx.THREE.AdditiveBlending
      });
      const overlayMesh = new Mesh(overlayGeo, overlayMat);
      overlayMesh.position.set(0.3, 0, 0.01);
      container.add(overlayMesh);
    }).catch((err) => {
      console.warn("Failed to load texture in pricing card label:", err);
    });
  }

  // Create thin borders accentuating the machined layout
  const borderGeo = new PlaneGeometry(width, 0.01);
  const borderMat = new MeshBasicNodeMaterial({ color: cAccent, transparent: true, opacity: 0.6 });
  const topBorder = new Mesh(borderGeo, borderMat);
  topBorder.position.set(0, height / 2, 0.01);
  container.add(topBorder);

  // Add text content
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.set(-width / 2 + 0.12, -0.05, 0.02);

  // Look for label or headline text
  let primaryText = "Pricing 1";
  for (const item of textItems) {
    if (item.text) {
      primaryText = item.text;
      break;
    }
  }

  // Render using ctx.fontAtlas (JetBrains Mono for tech-pricing vibe, or Lora serif header)
  const titleText = ctx.fontAtlas.createText(primaryText, {
    fontSize: 0.15, // matches ~39px in scale ratio
    color: cPaper,
    align: 'left'
  });
  textGroup.add(titleText);
  container.add(textGroup);

  // Applied cinematic primitives handler
  const primitivesCleanup = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    if (ctx.primitives[prim.name]) {
      const pInstance = ctx.primitives[prim.name](container, prim.params);
      if (pInstance) {
        if (pInstance.timeline) activeTimelines.push(pInstance.timeline);
        if (pInstance.cleanup) primitivesCleanup.push(pInstance.cleanup);
      }
    }
  }

  // Define standard exit / cleanup routine
  container.userData = {
    handlers: {},
    cleanup: () => {
      cardGeometry.dispose();
      material.dispose();
      borderGeo.dispose();
      borderMat.dispose();
      activeTimelines.forEach(tl => tl.kill());
      primitivesCleanup.forEach(fn => fn());
    }
  };

  return container;
}

// Pseudo-random fractional helper node for noise shading
function frac(node) {
  const { sub, floor } = require('three/tsl');
  return sub(node, floor(node));
}
